{{-- One token of a chat message (streamChat.js tokenize()): text, link, NIP-30 emoji, NIP-27 mention (@name chip: the player page for a league account, njump.me for anybody else) or reference (a "quoted message" chip to njump.me). Text is always x-text, never HTML. The scope (liveChat, gameChannel) gives nameOf(), mentionUrl(), mentionExternal() and t.quoted. --}}
<span class="contents"><span x-show="token.type === 'text'" x-text="token.type === 'text' ? token.value : ''"></span><a x-show="token.type === 'link'" :href="token.type === 'link' ? token.url : null" x-text="token.type === 'link' ? token.value : ''" target="_blank" rel="noopener noreferrer nofollow ugc" class="[overflow-wrap:anywhere] text-btc underline decoration-btc/40 underline-offset-2 hover:text-btc-hi"></a><img x-show="token.type === 'emoji'" :src="token.type === 'emoji' ? token.url : null" :alt="':' + token.value + ':'" :title="':' + token.value + ':'" referrerpolicy="no-referrer" loading="lazy" data-test="live-chat-emoji-img" class="inline-block h-[1.5em] w-auto max-w-[4em] align-[-0.4em] object-contain"><a x-show="token.type === 'mention'" :href="token.type === 'mention' ? mentionUrl(token) : null" :target="token.type === 'mention' && mentionExternal(token) ? '_blank' : null" :rel="token.type === 'mention' && mentionExternal(token) ? 'noopener noreferrer nofollow ugc' : null" :title="token.type === 'mention' && mentionExternal(token) ? @js(__('Open on njump.me')) : null" x-text="token.type === 'mention' ? '@' + nameOf(token.pubkey) : ''" data-test="chat-mention" class="rounded-tag bg-raised px-1 font-bold [overflow-wrap:anywhere] text-btc-hi [box-decoration-break:clone] hover:text-btc"></a><a x-show="token.type === 'ref'" :href="token.type === 'ref' ? token.url : null" target="_blank" rel="noopener noreferrer nofollow ugc" title="{{ __('Open on njump.me') }}" data-test="chat-ref" class="inline-block max-w-full rounded-tag px-1.5 text-xs leading-5 whitespace-nowrap text-ink-2 shadow-[inset_0_0_0_1px_var(--color-edge)] hover:text-ink"><x-icon name="chat" :size="12" class="mr-1 inline-block align-[-0.125em]" /><span x-text="t.quoted"></span></a></span>
